def texts():
    for name, body in (("inkscape-mm.svg", INKSCAPE),
                       ("illustrator-pt.svg", ILLUSTRATOR),
                       ("px-default.svg", PX_DEFAULT),
                       ("refuse-clip.svg", CLIPPED),
                       ("refuse-mask.svg", MASKED),
                       ("refuse-foreign.svg", FOREIGN),
                       ("two-cubes.obj", OBJ),
                       ("two-cubes.mtl", MTL)):
        with open(out(name), "w") as fh:
            fh.write(body)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--port", type=int, required=True)
    args = ap.parse_args()
    sys.path.insert(0, os.path.join(ROOT, "python"))
    from lobole.client import Client
    d = Client(args.port)
    step_boxes(d)
    flat_pattern(d)
    d.call("new_project")
    dxfs()
    texts()
    print("fixtures written to", HERE)


if __name__ == "__main__":
    main()
